import numpy as np
def shapes(g):
    a=np.array(g); seen=set(); res=[]
    for i in range(10):
        for j in range(10):
            if a[i,j] and (i,j) not in seen:
                c=a[i,j]; st=[(i,j)]; comp=set()
                while st:
                    y,x=st.pop()
                    if (y,x) in comp: continue
                    comp.add((y,x)); seen.add((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<10 and 0<=nx<10 and a[ny,nx]==c and (ny,nx) not in comp:
                            st.append((ny,nx))
                res.append((c,comp))
    return res
